import{_ as a,c as o,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"Privacy Policy","description":"qDiff does not collect your data. Read what the app reads on your Mac and how purchases are handled.","frontmatter":{"title":"Privacy Policy","description":"qDiff does not collect your data. Read what the app reads on your Mac and how purchases are handled."},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md","lastUpdated":1793948370000}'),r={name:"privacy/index.md"};function s(n,e,c,d,l,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><em>Last updated: 6 November 2026</em></p><p><strong>The short version: qDiff does not collect personal data.</strong> It is a local tool. Your files stay on your Mac.</p><h2 id="what-qdiff-reads" tabindex="-1">What qDiff reads <a class="header-anchor" href="#what-qdiff-reads" aria-label="Permalink to &quot;What qDiff reads&quot;">​</a></h2><p>qDiff opens only the files and folders you choose in the app, and processes them on your device to show the comparison. If you grant access to a folder, that access is kept for your convenience and can be removed in Settings at any time. Nothing is uploaded to us.</p><h2 id="what-we-do-not-do" tabindex="-1">What we do not do <a class="header-anchor" href="#what-we-do-not-do" aria-label="Permalink to &quot;What we do not do&quot;">​</a></h2><ul><li>We do not collect names, email addresses or usage statistics.</li><li>We do not track you across apps or websites.</li><li>We do not require an account or a sign-in.</li><li>We do not show advertising or include analytics or third-party tracking.</li><li>We do not sync or back up your files to any server.</li></ul><h2 id="network-access" tabindex="-1">Network access <a class="header-anchor" href="#network-access" aria-label="Permalink to &quot;Network access&quot;">​</a></h2><p>qDiff works offline. The only optional network request is the in-app “More Apps” page, which loads a public list of apps. That request contains no information about you, your files or your device, and no usage data is sent back.</p><h2 id="purchases" tabindex="-1">Purchases <a class="header-anchor" href="#purchases" aria-label="Permalink to &quot;Purchases&quot;">​</a></h2><p>The optional one-time purchase is handled entirely by the Mac App Store and your Apple ID. We never see your payment details. You can restore a purchase from Settings inside the app.</p><h2 id="this-website" tabindex="-1">This website <a class="header-anchor" href="#this-website" aria-label="Permalink to &quot;This website&quot;">​</a></h2><p>This site is a set of static pages. It has no login, no analytics and no advertising cookies. Opening a page does not require you to give us anything.</p><h2 id="children" tabindex="-1">Children <a class="header-anchor" href="#children" aria-label="Permalink to &quot;Children&quot;">​</a></h2><p>qDiff is not directed at children and does not knowingly collect information from anyone.</p><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><p>If this policy ever changes, we will update this page and the date above. Any change that affects what the app reads will also be described in the app itself.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions about privacy? Write to <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>.</p>',19)])])}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
